html:
{% set embedded = quotation_assets if quotation_assets is defined else {} %}
<style>
@font-face{font-family:Carlito;src:url('{{ embedded.get("regular_woff") or frappe.utils.get_url("/assets/fieldpulse/fonts/quotation/Carlito-Regular.woff") }}') format('woff'),url('{{ embedded.get("regular") or frappe.utils.get_url("/assets/fieldpulse/fonts/quotation/Carlito-Regular.ttf") }}') format('truetype');font-style:normal;font-weight:400;}
@font-face{font-family:Carlito;src:url('{{ embedded.get("bold_woff") or frappe.utils.get_url("/assets/fieldpulse/fonts/quotation/Carlito-Bold.woff") }}') format('woff'),url('{{ embedded.get("bold") or frappe.utils.get_url("/assets/fieldpulse/fonts/quotation/Carlito-Bold.ttf") }}') format('truetype');font-style:normal;font-weight:700;}
.print-format{font-family:Carlito,Calibri,Carlito,Arial,sans-serif!important;color:#082d50;font-size:11pt;line-height:1.4;padding:0!important;}
.print-format *{box-sizing:border-box;}.print-format table,.print-format th,.print-format td,.print-format h1{font-family:Carlito,Calibri,Arial,sans-serif!important;}
.dd-header,.dd-meta,.dd-items,.dd-summary,.dd-terms-table,.dd-split{width:100%;border-collapse:collapse;}
.dd-header{margin-bottom:5mm;}.dd-header td{vertical-align:middle;padding:0;}.dd-logo{width:54mm;height:auto;}.dd-document{text-align:right;}.dd-document h1{font-size:28pt;line-height:1.1;letter-spacing:1px;color:#00857c;margin:0 0 2mm;font-weight:700;}.dd-document .dd-caption{font-size:9pt;}
.dd-caption{color:#60758a;font-size:9pt;}.dd-meta{margin-bottom:5mm;}.dd-meta>tbody>tr>td{vertical-align:top;padding:0;}.dd-meta-left{width:57%;padding-right:12mm!important;}.dd-customer{text-align:right;}.dd-meta table{width:100%;border-collapse:collapse;}.dd-meta table td{padding:1.3mm 0;vertical-align:top;font-size:10.5pt;}.dd-meta table td:first-child{font-weight:700;width:39mm;}.dd-customer-label{font-size:9pt;font-weight:700;letter-spacing:.6px;color:#00857c;margin-bottom:3mm;}.dd-customer-name{font-size:14pt;font-weight:700;}.dd-customer-email{font-size:10pt;overflow-wrap:break-word;word-wrap:break-word;margin-top:1mm;}
.dd-section-rule{border-top:2px solid #00857c;margin-bottom:5mm;}.dd-items{table-layout:fixed;margin-bottom:5mm;}.dd-items thead{display:table-header-group;}.dd-items th{background:#00857c!important;color:#fff!important;font-size:10pt;font-weight:700;padding:3mm;text-align:left;}.dd-items td{background:#f2f6f7!important;padding:3mm;border-bottom:2px solid white;vertical-align:top;font-size:10.5pt;}.dd-items tr{page-break-inside:avoid;}.dd-items td+td{border-left:2px solid white;}.dd-item-title{font-weight:700;margin-bottom:1mm;}.dd-notes{white-space:pre-wrap;overflow-wrap:break-word;word-wrap:break-word;}.dd-item-scope{font-size:10pt;color:#40576b;}.dd-money{text-align:right!important;white-space:nowrap;}.dd-summary{width:57%;table-layout:fixed;margin-left:auto;margin-bottom:5mm;page-break-inside:avoid;}.dd-summary td{padding:1.7mm 3mm;font-size:10.5pt;vertical-align:top;}.dd-summary td:first-child{color:#40576b;}.dd-summary .dd-total td{font-weight:700;font-size:13pt;border-top:1px solid #c9d6dd;padding-top:3mm;padding-bottom:3mm;}.dd-summary .dd-total .dd-money{background:#082d50!important;color:#fff!important;border-top-color:#082d50;}.dd-split{page-break-inside:avoid;margin:4mm 0 6mm;background:#eef7f6;}.dd-split td{width:50%;padding:3mm 4mm;font-size:10pt;vertical-align:top;}.dd-split td+td{border-left:2px solid white;}.dd-split strong{display:block;font-size:13pt;margin-top:1mm;}.dd-split .dd-caption{color:#476774;}
.dd-terms{border-top:2px solid #00857c;padding-top:4mm;page-break-inside:avoid;}.dd-terms-table td{vertical-align:top;font-size:10pt;padding:0;}.dd-terms-table td:first-child{width:36mm;padding-right:5mm;font-weight:700;font-size:9pt;letter-spacing:.4px;}.dd-terms p{margin:0 0 2mm;}.dd-terms p:last-child{margin-bottom:0;}.dd-footer{page-break-inside:avoid;margin-top:4mm;border-top:1px solid #dce5e9;padding-top:3mm;color:#60758a;font-size:9pt;}
</style>
<table class="dd-header"><tr><td><img class="dd-logo" src="{{ embedded.get('logo') or frappe.utils.get_url('/assets/fieldpulse/images/DD_logo.png') }}" alt="Diaspora Desk" /></td><td class="dd-document"><h1>QUOTATION</h1><div class="dd-caption">{{ doc.status | e }}{% if doc.accepted_at %} &middot; {{ frappe.utils.formatdate(doc.accepted_at) }}{% endif %}</div></td></tr></table>
<table class="dd-meta"><tr><td class="dd-meta-left"><table><tr><td>Quotation No.</td><td>{{ doc.name | e }}</td></tr><tr><td>Request reference</td><td>{{ doc.request | e }}</td></tr><tr><td>Issue date</td><td>{{ frappe.utils.formatdate(doc.quotation_date) }}</td></tr><tr><td>Valid until</td><td>{{ frappe.utils.formatdate(doc.valid_until) }}</td></tr><tr><td>Currency</td><td>{{ doc.currency | e }}</td></tr>{% if doc.agreed_completion_date %}<tr><td>Expected completion</td><td>{{ frappe.utils.formatdate(doc.agreed_completion_date) }}</td></tr>{% endif %}</table></td><td class="dd-customer"><div class="dd-customer-label">PREPARED FOR</div><div class="dd-customer-name">{{ doc.customer_name | e }}</div><div class="dd-customer-email">{{ doc.customer_email | e }}</div></td></tr></table>
<div class="dd-section-rule"></div>
<table class="dd-items"><thead><tr><th style="width:76%">Project Description</th><th class="dd-money" style="width:24%">Amount ({{ doc.currency | e }})</th></tr></thead><tbody>
{% for item in doc.items %}<tr><td><div class="dd-item-title">{{ item.project_title | e }}</div>{% if item.description != item.project_title %}<div class="dd-notes dd-item-scope">{{ item.description | e }}</div>{% endif %}<div class="dd-caption">Planned scouts: {{ item.get('planned_scouts') or 1 }}</div></td><td class="dd-money">{{ '{:,.2f}'.format(item.amount) }}</td></tr>{% endfor %}
</tbody></table>
<table class="dd-summary"><colgroup><col style="width:57.894737%"><col style="width:42.105263%"></colgroup>
{% if doc.get('subtotal') is not none and doc.get('subtotal') %}<tr><td>Subtotal{% if doc.get('tax_inclusive') %} (VAT inclusive){% endif %}</td><td class="dd-money">{{ doc.currency | e }} {{ '{:,.2f}'.format(doc.subtotal) }}</td></tr>
{% if doc.get('discount_amount') %}<tr><td>Discount{% if doc.get('discount_type') == 'Percentage' %} ({{ doc.discount_value }}%){% endif %}</td><td class="dd-money">-{{ doc.currency | e }} {{ '{:,.2f}'.format(doc.discount_amount) }}</td></tr>{% endif %}
{% if doc.get('tax_inclusive') %}<tr><td>Net before VAT</td><td class="dd-money">{{ doc.currency | e }} {{ '{:,.2f}'.format(doc.taxable_amount) }}</td></tr>{% endif %}<tr><td>VAT ({{ doc.vat_rate }}%)</td><td class="dd-money">{{ doc.currency | e }} {{ '{:,.2f}'.format(doc.vat_amount) }}</td></tr>{% endif %}
<tr class="dd-total"><td>Total payable</td><td class="dd-money">{{ doc.currency | e }} {{ '{:,.2f}'.format(doc.total) }}</td></tr></table>
{% if doc.get('deposit_amount') %}<table class="dd-split"><tr><td><span class="dd-caption">50% deposit &middot; upfront</span><strong>{{ doc.currency | e }} {{ '{:,.2f}'.format(doc.deposit_amount) }}</strong></td><td><span class="dd-caption">50% balance &middot; after report review</span><strong>{{ doc.currency | e }} {{ '{:,.2f}'.format(doc.balance_amount) }}</strong></td></tr></table>{% endif %}
<div class="dd-terms"><table class="dd-terms-table"><tr><td>TERMS &amp;<br>CONDITIONS</td><td><p class="dd-notes">{{ (doc.terms or "50% upfront; balance after report review. Scope changes require a revised quote.") | e }}</p></td></tr></table></div>
